import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../Estilo/Detalhes.css'; // Caminho para o CSS

function Detalhes() {
  const [data, setData] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('https://requestuser.free.beeceptor.com');
        setData(response.data);
      } catch (error) {
        setError('Ocorreu um erro ao buscar os dados.');
        console.error('Erro na requisição:', error);
      }
    };

    fetchData();
  }, []);

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>
        {error && <p className="text-red-500">{error}</p>}
        {data.length === 0 ? (
          <p>Nenhum dado cadastrado.</p>
        ) : (
          data.map((item, index) => (
            <div key={index} className="mb-4 card">
              <p><strong>Nome Completo:</strong> {item.nomeCompleto}</p>
              <p><strong>Data de Nascimento:</strong> {item.dataNascimento}</p>
              <p><strong>Telefone:</strong> {item.telefone}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Detalhes;
